"""Complete operator-driven graph: launch → freeze → verify → review → approve → integrate.

No agent starts without `start --live`. Operator controls are local CLI-only.
"""
from __future__ import annotations

import argparse
import hashlib
import html
import json
import os
import re
import subprocess
import threading
from pathlib import Path
from typing import TypedDict

from langgraph.checkpoint.sqlite import SqliteSaver
from langgraph.graph import END, START, StateGraph
from langgraph.types import Command, interrupt

from .checks import now, recheck_packet, verify_revision
from .interactive import InteractiveSessions, attach_panels
from .sessions import NODES, git, prepare, read_json, run_lock, save_json
from .verification import owns, policy_digest, safe_path, validate_policy


def digest_file(path: Path) -> str:
    with path.open("rb") as handle:
        return hashlib.file_digest(handle, "sha256").hexdigest()


def commit_env() -> dict:
    env = dict(os.environ)
    env.update(GIT_AUTHOR_NAME="Workflow snapshot", GIT_AUTHOR_EMAIL="workflow@localhost",
               GIT_COMMITTER_NAME="Workflow snapshot", GIT_COMMITTER_EMAIL="workflow@localhost")
    return env


def changed_files(cwd: Path, base: str) -> list[str]:
    tracked = subprocess.check_output(["git", "-C", str(cwd), "diff", "--no-renames", "--name-only", "-z", base]).decode().split("\0")
    untracked = subprocess.check_output(["git", "-C", str(cwd), "ls-files", "--others", "--exclude-standard", "-z"]).decode().split("\0")
    return sorted(set(filter(None, tracked + untracked)))


class PipelineState(TypedDict, total=False):
    run_id: str
    ui: dict
    adapter: dict
    snapshots: dict
    ui_packet: str
    adapter_packet: str
    bundle: str
    review: dict
    approved_bundle: str
    integrated_commit: str


class Pipeline:
    def __init__(self, directory: Path, sessions=None):
        self.directory = directory.resolve()
        self.plan = read_json(self.directory / "plan.json")
        self.policy = validate_policy(read_json(self.directory / "policy.json"))
        if self.plan.get("policy_sha256") != policy_digest(self.policy):
            raise ValueError("Pinned policy changed")
        if {worker["node_id"] for worker in self.policy["workers"]} != set(NODES):
            raise ValueError("This small graph requires policy nodes ui and adapter")
        self.sessions = sessions or InteractiveSessions(self.directory, timeout=45)
        self._events_lock = threading.Lock()

    def event(self, node: str, status: str, message: str):
        with self._events_lock:
            path = self.directory / "events.jsonl"
            prior = path.read_text().splitlines() if path.exists() else []
            sequence = json.loads(prior[-1])["sequence"] + 1 if prior else 1
            record = {"sequence": sequence, "time": now(), "node": node, "status": status, "message": message}
            with path.open("a") as handle:
                handle.write(json.dumps(record) + "\n")
                handle.flush()
                os.fsync(handle.fileno())

    def launch(self, node: str) -> dict:
        self.event(node, "running", "Launching or reconciling the exact native session")
        try:
            receipt = self.sessions.run(node)
        except Exception as error:
            self.event(node, "blocked", str(error))
            raise
        self.event(node, "interactive", "Awaiting explicit human handoff; idle is not acceptance")
        return receipt

    def stop_workers(self):
        """Persist native identity before stopping. Never signal guessed/reused PIDs."""
        for node in NODES:
            marker = self.directory / f"{node}.stop.json"
            if marker.exists():
                intent = read_json(marker)
            else:
                row = self.sessions.locate(node, self.sessions.inventory())
                if row is None:
                    raise RuntimeError("Worker missing before freeze; reconcile before snapshotting")
                intent = {"background_id": row["id"], "session_id": row["sessionId"], "pid": row["pid"], "stopped": False}
                save_json(marker, intent)
            if not intent["stopped"]:
                result = subprocess.run([self.sessions.executable, "stop", intent["background_id"]], capture_output=True, text=True, timeout=20)
                if result.returncode != 0:
                    raise RuntimeError(f"Stop failed for {node}; inspect native session before retrying")
                # CLI's successful stop is not enough if the live registry still has it.
                rows = self.sessions.inventory()
                if any(row.get("sessionId") == intent["session_id"] and row.get("pid") for row in rows):
                    raise RuntimeError("Native worker still reports a live PID after stop; retry freeze after reconciliation")
                intent["stopped"] = True
                save_json(marker, intent)
        self.event("freeze", "stopped", "Both native workers stopped before snapshot capture")

    def freeze(self) -> dict:
        record = self.directory / "snapshots.json"
        if record.exists():
            return read_json(record)
        self.stop_workers()
        snapshots = {}
        for node in NODES:
            worker = next(item for item in self.policy["workers"] if item["node_id"] == node)
            cwd = Path(self.plan["nodes"][node]["worktree"])
            if git(cwd, "rev-parse", "HEAD") != self.plan["base_commit"]:
                raise ValueError("Worker changed HEAD; reconcile commits rather than silently accepting them")
            changed = changed_files(cwd, self.plan["base_commit"])
            for name in changed:
                safe_path(name)
                if not any(owns(name, safe_path(prefix)) for prefix in worker["owned_paths"]):
                    raise ValueError(f"{node} edited unowned path: {name}")
                if (cwd / name).is_symlink():
                    raise ValueError("Symlink changes require manual review before snapshot")
            index = self.directory / f"{node}.snapshot-index"
            if index.exists():
                index.unlink()  # Only our private temporary index, never a user's index.
            env = commit_env()
            env["GIT_INDEX_FILE"] = str(index)
            subprocess.run(["git", "-C", str(cwd), "read-tree", self.plan["base_commit"]], env=env, check=True)
            subprocess.run(["git", "-C", str(cwd), "add", "-A", "--", "."], env=env, check=True)
            tree = subprocess.check_output(["git", "-C", str(cwd), "write-tree"], env=env, text=True).strip()
            # Validate paths from the actual captured tree, including staged renames/deletes.
            captured = git(cwd, "diff-tree", "--no-commit-id", "--no-renames", "--name-only", "-r", self.plan["base_commit"], tree).splitlines()
            if sorted(captured) != changed:
                raise ValueError("Files changed during snapshot; refuse inconsistent evidence")
            commit = self.plan["base_commit"]
            if changed:
                commit = subprocess.check_output(["git", "-C", str(cwd), "-c", "commit.gpgsign=false", "commit-tree", tree,
                                                  "-p", self.plan["base_commit"], "-m", f"Workflow {self.plan['run_id']}: {node}"], env=env, text=True).strip()
            ref = f"refs/workflow/{hashlib.sha256(str(self.directory).encode()).hexdigest()[:16]}/{node}"
            subprocess.run(["git", "-C", str(cwd), "update-ref", ref, commit], check=True)
            handoff_path = self.directory / f"{node}.handoff.json"
            if not handoff_path.exists():
                raise ValueError(f"Missing {node} handoff: summary and open_assumptions are required")
            handoff = read_json(handoff_path)
            if set(handoff) != {"summary", "open_assumptions"} or not isinstance(handoff["summary"], str) or not handoff["summary"].strip() or not isinstance(handoff["open_assumptions"], list) or any(not isinstance(item, str) for item in handoff["open_assumptions"]):
                raise ValueError("Malformed worker handoff")
            receipt = read_json(self.directory / f"{node}.interactive.json")
            snapshots[node] = {"commit": commit, "changed_files": changed, "session_id": receipt["session_id"], **handoff}
        save_json(record, snapshots)
        self.event("freeze", "succeeded", "Immutable snapshots captured; worker-reported checks are not trusted")
        return snapshots

    def attempt(self, phase: str, node: str) -> int:
        path = self.directory / "attempts.json"
        return read_json(path).get(f"{phase}:{node}", 1) if path.exists() else 1

    def verify(self, node: str, snapshots: dict) -> str:
        snap = snapshots[node]
        attempt = self.attempt("worker", node)
        self.event(f"verify_{node}", "running", f"Attempt {attempt}; revision {snap['commit']}")
        packet = verify_revision(self.directory, self.plan, self.policy, node, snap["commit"], snap["changed_files"], snap["session_id"], attempt=attempt)
        path = self.directory / "verification" / "worker" / node / str(attempt) / "packet.json"
        packet["result"]["summary"] = snap["summary"]
        packet["result"]["open_assumptions"] = snap["open_assumptions"]
        save_json(path, packet)
        self.event(f"verify_{node}", packet["gate"]["status"], "; ".join(packet["gate"]["reasons"]) or "Required tests and artifacts passed")
        if packet["gate"]["status"] != "passed":
            raise RuntimeError(f"{node} verification blocked; see {path}. Retry explicitly or start a revised run.")
        return str(path)

    def candidate(self, state: PipelineState) -> str:
        # Validate branch evidence again before combining anything.
        worker_paths = [Path(state[f"{node}_packet"]) for node in NODES]
        for path in worker_paths:
            packet = recheck_packet(read_json(path), self.policy, self.directory)
            if packet["gate"]["status"] != "passed":
                raise ValueError("Worker evidence no longer passes")
        saved = self.directory / "candidate.json"
        if saved.exists():
            candidate = read_json(saved)
        else:
            cwd = self.directory / "candidate"
            if cwd.exists():
                raise ValueError("Partial candidate worktree exists; inspect before recovery")
            subprocess.run(["git", "-C", self.plan["repository"], "worktree", "add", "--detach", str(cwd), self.plan["base_commit"]], check=True, capture_output=True)
            for node in NODES:
                commit = state["snapshots"][node]["commit"]
                if commit != self.plan["base_commit"]:
                    subprocess.run(["git", "-C", str(cwd), "-c", "core.hooksPath=/dev/null", "-c", "commit.gpgsign=false", "cherry-pick", commit], env=commit_env(), check=True, capture_output=True)
            candidate = {"commit": git(cwd, "rev-parse", "HEAD"), "worktree": str(cwd)}
            save_json(saved, candidate)
        candidate_paths = []
        for node in NODES:
            attempt = self.attempt("candidate", node)
            packet = verify_revision(self.directory, self.plan, self.policy, node, candidate["commit"],
                                     changed_files(Path(candidate["worktree"]), self.plan["base_commit"]),
                                     state["snapshots"][node]["session_id"], phase="candidate", attempt=attempt)
            path = self.directory / "verification" / "candidate" / node / str(attempt) / "packet.json"
            self.event(f"candidate_{node}", packet["gate"]["status"], f"Combined revision {candidate['commit']}")
            if packet["gate"]["status"] != "passed":
                raise RuntimeError(f"Combined candidate failed {node} checks; see {path}")
            candidate_paths.append(path)
        bundle = {"run_id": self.plan["run_id"], "base_commit": self.plan["base_commit"],
                  "candidate_commit": candidate["commit"], "policy_sha256": policy_digest(self.policy),
                  "snapshots": state["snapshots"],
                  "packets": [{"path": str(path), "sha256": digest_file(path)} for path in worker_paths + candidate_paths]}
        path = self.directory / "review-bundle.json"
        save_json(path, bundle)
        return str(path)

    def validate_bundle(self) -> tuple[dict, str]:
        path = self.directory / "review-bundle.json"
        bundle = read_json(path)
        if bundle["run_id"] != self.plan["run_id"] or bundle["policy_sha256"] != policy_digest(self.policy):
            raise ValueError("Bundle identity/policy changed")
        for reference in bundle["packets"]:
            packet_path = Path(reference["path"]).resolve()
            if not packet_path.is_relative_to(self.directory) or digest_file(packet_path) != reference["sha256"]:
                raise ValueError("Review evidence changed")
            packet = recheck_packet(read_json(packet_path), self.policy, self.directory)
            if packet["gate"]["status"] != "passed":
                raise ValueError("Review artifact missing, changed or failing")
        return bundle, digest_file(path)

    def validate_review(self, review: dict) -> None:
        bundle, digest = self.validate_bundle()
        required = {"run_id", "bundle_sha256", "candidate_commit", "reviewer", "independent", "verdict", "findings"}
        if set(review) != required or review["run_id"] != bundle["run_id"] or review["bundle_sha256"] != digest or review["candidate_commit"] != bundle["candidate_commit"]:
            raise ValueError("Review must reference this exact run, bundle hash and candidate")
        worker_ids = {item["session_id"] for item in bundle["snapshots"].values()}
        if review["independent"] is not True or not isinstance(review["reviewer"], str) or not review["reviewer"].strip() or review["reviewer"] in worker_ids:
            raise ValueError("Independent reviewer identity required")
        if review["verdict"] != "approved" or not isinstance(review["findings"], list):
            raise ValueError("Review is not approved")
        for finding in review["findings"]:
            if not isinstance(finding, dict) or set(finding) != {"severity", "message", "disposition"} or finding["severity"] not in {"P0", "P1", "P2"} or finding["disposition"] not in {"open", "resolved", "accepted"} or not isinstance(finding["message"], str) or not finding["message"].strip():
                raise ValueError("Malformed review finding")
            if finding["severity"] in {"P0", "P1"} and finding["disposition"] != "resolved":
                raise ValueError("Unresolved blocking review finding")

    def integrate(self, approved: str) -> str:
        bundle, digest = self.validate_bundle()
        review = read_json(self.directory / "review.json")
        self.validate_review(review)
        if approved != digest:
            raise ValueError("Approval references stale evidence")
        repo = Path(self.plan["repository"])
        candidate = bundle["candidate_commit"]
        intent = self.directory / "integration-intent.json"
        if git(repo, "symbolic-ref", "--short", "HEAD") != self.plan["source_branch"]:
            raise ValueError("Source branch changed")
        if git(repo, "status", "--porcelain"):
            raise ValueError("Source worktree is dirty; refusing integration")
        if intent.exists():
            if read_json(intent) != {"bundle_sha256": digest, "candidate_commit": candidate}:
                raise ValueError("Integration intent changed")
            if git(repo, "rev-parse", "HEAD") == candidate:
                return candidate
        if git(repo, "rev-parse", "HEAD") != self.plan["base_commit"]:
            raise ValueError("Source advanced since preparation; rebase/review explicitly")
        save_json(intent, {"bundle_sha256": digest, "candidate_commit": candidate})
        subprocess.run(["git", "-C", str(repo), "-c", "core.hooksPath=/dev/null", "merge", "--ff-only", candidate], check=True, capture_output=True)
        self.event("integrate", "succeeded", f"Fast-forwarded to {candidate}; no push performed")
        return candidate


def build_pipeline(checkpointer, runtime: Pipeline):
    def ui(_state): return {"ui": runtime.launch("ui")}
    def adapter(_state): return {"adapter": runtime.launch("adapter")}
    def handoff(_state):
        decision = interrupt({"kind": "worker_handoff", "message": "Type in Claude terminals; provide both handoffs, then explicitly freeze."})
        if decision != {"freeze": True}:
            raise ValueError("Explicit freeze required")
        return {"snapshots": runtime.freeze()}
    def verify_ui(state): return {"ui_packet": runtime.verify("ui", state["snapshots"])}
    def verify_adapter(state): return {"adapter_packet": runtime.verify("adapter", state["snapshots"])}
    def candidate(state): return {"bundle": runtime.candidate(state)}
    def review(_state):
        _, digest = runtime.validate_bundle()
        decision = interrupt({"kind": "independent_review", "bundle_sha256": digest,
                              "bundle_path": str(runtime.directory / "review-bundle.json")})
        runtime.validate_review(decision)
        save_json(runtime.directory / "review.json", decision)
        runtime.event("review", "approved", decision["reviewer"])
        return {"review": decision}
    def approval(_state):
        _, digest = runtime.validate_bundle()
        decision = interrupt({"kind": "integration_approval", "bundle_sha256": digest,
                              "message": "Approve fast-forward of source branch; no push."})
        if decision != {"approve": digest}:
            raise ValueError("Explicit exact-bundle approval required")
        return {"approved_bundle": digest}
    def integrate(state): return {"integrated_commit": runtime.integrate(state["approved_bundle"])}
    graph = StateGraph(PipelineState)
    for name, function in (("launch_ui", ui), ("launch_adapter", adapter), ("handoff", handoff),
                           ("verify_ui", verify_ui), ("verify_adapter", verify_adapter), ("candidate", candidate),
                           ("review", review), ("approval", approval), ("integrate", integrate)):
        graph.add_node(name, function)
    graph.add_edge(START, "launch_ui"); graph.add_edge(START, "launch_adapter")
    graph.add_edge(["launch_ui", "launch_adapter"], "handoff")
    graph.add_edge("handoff", "verify_ui"); graph.add_edge("handoff", "verify_adapter")
    graph.add_edge(["verify_ui", "verify_adapter"], "candidate")
    graph.add_edge("candidate", "review"); graph.add_edge("review", "approval")
    graph.add_edge("approval", "integrate"); graph.add_edge("integrate", END)
    return graph.compile(checkpointer=checkpointer)


def report(runtime: Pipeline, state) -> Path:
    """Escaped local results viewer, generated on every CLI boundary; no server needed."""
    events_path = runtime.directory / "events.jsonl"
    events = [json.loads(line) for line in events_path.read_text().splitlines()] if events_path.exists() else []
    packets = list((runtime.directory / "verification").glob("*/*/*/packet.json"))
    parts = ['<!doctype html><meta charset="utf-8"><title>Workflow report</title><style>body{font:16px system-ui;max-width:1100px;margin:40px auto;background:#151820;color:#eee}pre{white-space:pre-wrap}a{color:#8dcaff}img{max-width:100%}section{border:1px solid #555;padding:16px;margin:16px 0}</style>',
             '<h1>Workflow report</h1><p>Launch workers → human handoff → isolated checks → combined checks → independent review → approval → integration</p>',
             '<h2>Current state</h2><pre>' + html.escape(json.dumps({"next": state.next, "interrupts": [str(task.interrupts) for task in state.tasks if task.interrupts], "errors": [str(task.error) for task in state.tasks if task.error], "integrated_commit": state.values.get("integrated_commit")}, indent=2)) + '</pre>',
             '<h2>Timeline</h2><pre>' + html.escape(json.dumps(events, indent=2)) + '</pre>']
    from urllib.parse import quote
    for path in packets:
        packet = read_json(path)
        parts.append('<section><h2>' + html.escape(str(path.relative_to(runtime.directory))) + '</h2><pre>' + html.escape(json.dumps({"gate": packet["gate"], "result": packet["result"]}, indent=2)) + '</pre>')
        for artifact in packet["result"]["artifacts"]:
            local = Path(packet["artifact_paths"][artifact["artifact_id"]]).resolve()
            if not local.is_relative_to(runtime.directory):
                continue
            url = quote(str(local.relative_to(runtime.directory)), safe="/")
            parts.append(f'<p><a href="{url}">{html.escape(artifact["artifact_id"])}</a></p>')
            if artifact["kind"] == "screenshot":
                parts.append(f'<img alt="Browser scenario screenshot" src="{url}">')
        parts.append('</section>')
    destination = runtime.directory / "report.html"
    destination.write_text("\n".join(parts))
    return destination


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("action", choices=["prepare", "start", "attach", "freeze", "retry", "review", "approve", "status"])
    parser.add_argument("directory", type=Path)
    parser.add_argument("--repo", type=Path, default=Path.cwd())
    parser.add_argument("--policy", type=Path)
    parser.add_argument("--ui-task", type=Path)
    parser.add_argument("--adapter-task", type=Path)
    parser.add_argument("--live", action="store_true")
    parser.add_argument("--herdr", action="store_true")
    parser.add_argument("--review-file", type=Path)
    parser.add_argument("--bundle-sha256")
    parser.add_argument("--node", choices=NODES)
    parser.add_argument("--phase", choices=["worker", "candidate"], default="worker")
    args = parser.parse_args()
    directory = args.directory.resolve()
    try:
        if args.action == "prepare":
            if not all((args.policy, args.ui_task, args.adapter_task)):
                parser.error("prepare requires --policy and both task files")
            policy = validate_policy(read_json(args.policy))
            if {worker["node_id"] for worker in policy["workers"]} != set(NODES):
                parser.error("This graph requires policy nodes ui and adapter")
            tasks = {"ui": args.ui_task.read_text(), "adapter": args.adapter_task.read_text()}
            for worker in policy["workers"]:
                tasks[worker["node_id"]] += "\nApproved ownership and checks:\n" + json.dumps(worker)
            plan = prepare(directory, args.repo, "HEAD", tasks, True)
            plan.update(mode="interactive", policy_sha256=policy_digest(policy), source_branch=git(args.repo.resolve(), "symbolic-ref", "--short", "HEAD"))
            save_json(directory / "policy.json", policy)
            save_json(directory / "plan.json", plan)
            print(f"Prepared {directory}; no agents launched. Pin: {plan['base_commit']}")
            return
        with run_lock(directory):
            runtime = Pipeline(directory)
            if args.action == "attach":
                print(json.dumps(attach_panels(runtime.sessions), indent=2)); return
            with SqliteSaver.from_conn_string(str(directory / "pipeline.sqlite")) as saver:
                graph = build_pipeline(saver, runtime)
                config = {"configurable": {"thread_id": runtime.plan["run_id"]}, "max_concurrency": 2}
                state = graph.get_state(config)
                pending = [item.value.get("kind") for task in state.tasks for item in task.interrupts]
                value = None
                if args.action == "start":
                    if not args.live:
                        parser.error("start requires --live; do not use it for offline tests")
                    if state.values:
                        parser.error("Run already started; use status/explicit controls, never start again")
                    value = {"run_id": runtime.plan["run_id"]}
                elif args.action == "freeze":
                    if pending != ["worker_handoff"]:
                        parser.error("Run is not waiting for worker handoff")
                    value = Command(resume={"freeze": True})
                elif args.action == "review":
                    if pending != ["independent_review"] or not args.review_file:
                        parser.error("Review requires pending review and --review-file")
                    decision = read_json(args.review_file)
                    runtime.validate_review(decision)
                    value = Command(resume=decision)
                elif args.action == "approve":
                    if pending != ["integration_approval"]:
                        parser.error("Run is not waiting for integration approval")
                    _, digest = runtime.validate_bundle()
                    if args.bundle_sha256 != digest:
                        parser.error("Provide the exact --bundle-sha256 displayed at approval")
                    value = Command(resume={"approve": digest})
                elif args.action == "retry":
                    if not state.values or pending or not state.next:
                        parser.error("Retry requires a failed graph step, not an interrupt/completed run")
                    if args.node:
                        step = f"verify_{args.node}" if args.phase == "worker" else "candidate"
                        if step not in state.next:
                            parser.error("Selected check is not a failed/pending step")
                        attempts_path = directory / "attempts.json"
                        attempts = read_json(attempts_path) if attempts_path.exists() else {}
                        key = f"{args.phase}:{args.node}"
                        attempts[key] = attempts.get(key, 1) + 1
                        save_json(attempts_path, attempts)
                    # No new agent launch is ever permitted during retry.
                    if any(step.startswith("launch_") for step in state.next):
                        parser.error("Launch failure requires explicit session reconciliation; do not blindly retry")
                if args.action != "status":
                    try:
                        graph.invoke(value, config)
                    finally:
                        print(f"Report: {report(runtime, graph.get_state(config))}")
                    if args.action == "start" and args.herdr:
                        print(json.dumps(attach_panels(runtime.sessions), indent=2))
                else:
                    print(json.dumps({"next": state.next, "pending": pending, "errors": [str(task.error) for task in state.tasks if task.error]}, indent=2))
                    print(f"Report: {report(runtime, state)}")
    except (ValueError, RuntimeError, OSError, subprocess.SubprocessError) as error:
        parser.exit(1, f"Blocked: {error}\nAll work/evidence retained at {directory}. No automatic fallback or push.\n")


if __name__ == "__main__":
    main()

"""Local, isolated check execution and artifact capture. Never launches agents."""
from __future__ import annotations

import hashlib
import json
import os
import re
import shlex
import signal
import shutil
import subprocess
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

from .sessions import git, save_json, terminate
from .verification import evaluate_worker, policy_digest


def now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def execute(argv: list[str], cwd: Path, log: Path, timeout: int, env: dict) -> tuple[int, str, str]:
    started = now()
    with log.open("wb") as output:
        process = subprocess.Popen(argv, cwd=cwd, env=env, stdin=subprocess.DEVNULL,
                                   stdout=output, stderr=subprocess.STDOUT, start_new_session=True)
        try:
            code = process.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            terminate(process)
            output.write(b"\nWORKFLOW: timeout; process group terminated\n")
            code = 124
        except BaseException:
            terminate(process)
            raise
        finally:
            # Test runners must not leave servers or descendant writers alive.
            # terminate also signals the group after the group leader has exited.
            terminate(process)
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
            output.flush()
            os.fsync(output.fileno())
    return code, started, now()


def text_test_counts(log: str) -> dict | None:
    text = re.sub(r"\x1b\[[0-?]*[ -/]*[@-~]", "", log)
    unit = re.search(r"^Ran (\d+) tests? in .+$", text, re.MULTILINE)
    if unit:
        total = int(unit[1])
        skipped = re.search(r"\bskipped=(\d+)", text)
        skipped = int(skipped[1]) if skipped else 0
        failures = sum(int(value) for value in re.findall(r"\b(?:failures|errors|unexpected successes)=(\d+)", text))
        if not re.search(r"^(?:OK(?:\s|$)|FAILED\s*\()", text, re.MULTILINE):
            return None
        return {"passed": max(0, total - skipped - failures), "failed": failures, "skipped": skipped}
    # Node's TAP and spec reporters. Require a complete self-consistent summary.
    counts = {}
    for key in ("tests", "pass", "fail", "skipped", "cancelled", "todo"):
        found = re.findall(rf"^[#ℹ]\s+{key}\s+(\d+)\s*$", text, re.MULTILINE)
        if found:
            counts[key] = int(found[-1])
    if {"tests", "pass", "fail", "skipped"} <= counts.keys():
        if sum(counts.get(key, 0) for key in ("pass", "fail", "skipped", "cancelled", "todo")) == counts["tests"]:
            return {"passed": counts["pass"], "failed": counts["fail"] + counts.get("cancelled", 0),
                    "skipped": counts["skipped"] + counts.get("todo", 0)}
    return None


class Capture:
    def __init__(self, directory: Path):
        self.directory = directory
        self.artifacts = []
        self.paths = {}

    def add(self, source: Path, kind: str) -> str:
        if not source.is_file() or source.is_symlink():
            raise ValueError("Evidence must be a regular file")
        content = source.read_bytes()
        digest = hashlib.sha256(content).hexdigest()
        artifact_id = f"{kind}-{len(self.artifacts)}-{digest[:12]}"
        destination = self.directory / artifact_id
        with destination.open("xb") as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        destination.chmod(0o400)
        self.artifacts.append({"artifact_id": artifact_id, "kind": kind,
                               "uri": destination.name, "sha256": digest})
        self.paths[artifact_id] = destination
        return artifact_id


def browser_evidence(report_path: Path, output_root: Path, requirement: dict, capture: Capture) -> tuple[dict, list]:
    report = json.loads(report_path.read_text())
    if report.get("errors"):
        raise ValueError("Playwright reported global errors")
    specs = []
    def walk(suite):
        specs.extend(suite.get("specs", []))
        for child in suite.get("suites", []):
            walk(child)
    walk(report)
    required = {case["id"] for case in requirement["scenarios"]}
    found = {}
    counts = {"passed": 0, "failed": 0, "skipped": 0}
    for spec in specs:
        for test in spec.get("tests", []):
            results = test.get("results", [])
            # No flaky retries or expected failures counted as passing verification.
            passed = test.get("status") == "expected" and test.get("expectedStatus") == "passed" and len(results) == 1 and results[0].get("status") == "passed"
            skipped = test.get("status") == "skipped"
            counts["passed" if passed else "skipped" if skipped else "failed"] += 1
            matches = set(re.findall(r"\[scenario:([^\]]+)\]", spec.get("title", ""))) & required
            for scenario_id in matches:
                if scenario_id in found:
                    raise ValueError(f"Duplicate browser scenario/project result: {scenario_id}")
                screenshot = None
                if passed:
                    attachments = [item for item in results[0].get("attachments", [])
                                   if item.get("name") == f"screenshot:{scenario_id}" and item.get("contentType") == "image/png"]
                    if len(attachments) != 1:
                        raise ValueError(f"Expected one screenshot attachment for {scenario_id}")
                    path = Path(attachments[0].get("path", "")).resolve(strict=True)
                    if not path.is_relative_to(output_root.resolve()):
                        raise ValueError("Screenshot attachment outside isolated browser output directory")
                    screenshot = capture.add(path, "screenshot")
                found[scenario_id] = {"id": scenario_id, "status": "passed" if passed else "skipped" if skipped else "failed",
                                      "screenshot_artifact_id": screenshot}
    if set(found) != required:
        raise ValueError("Playwright report does not cover every required scenario")
    return counts, list(found.values())


def verify_revision(run: Path, plan: dict, policy: dict, node: str, commit: str, changed: list[str],
                    session_id: str, phase: str = "worker", attempt: int = 1) -> dict:
    """One fresh verification worktree per node/phase/attempt, artifacts retained."""
    worker = next(worker for worker in policy["workers"] if worker["node_id"] == node)
    directory = run / "verification" / phase / node / str(attempt)
    packet_path = directory / "packet.json"
    if packet_path.exists():
        packet = json.loads(packet_path.read_text())
        if packet["expected"]["output_commit"] != commit or packet["evidence"]["policy_sha256"] != policy_digest(policy):
            raise ValueError("Existing verification belongs to a different revision/policy")
        return recheck_packet(packet, policy, run)
    if directory.exists():
        raise RuntimeError("Interrupted check attempt exists; use an explicitly incremented attempt")
    directory.mkdir(parents=True, mode=0o700)
    worktree = directory / "worktree"
    subprocess.run(["git", "-C", plan["repository"], "worktree", "add", "--detach", str(worktree), commit], check=True, capture_output=True)
    if git(worktree, "rev-parse", "HEAD") != commit or git(worktree, "status", "--porcelain"):
        raise RuntimeError("Verification worktree did not start clean at expected revision")
    artifacts_dir = directory / "artifacts"
    artifacts_dir.mkdir()
    capture = Capture(artifacts_dir)
    env = {key: value for key, value in os.environ.items() if not key.startswith("HERDR_")}
    # Share installed browser executables read-only, not profiles or test caches.
    if sys.platform == "linux":
        env.setdefault("PLAYWRIGHT_BROWSERS_PATH", str(Path(env.get("XDG_CACHE_HOME", str(Path.home() / ".cache"))) / "ms-playwright"))
    env.update(PATH=str(Path(sys.executable).parent) + os.pathsep + env.get("PATH", ""),
               PYTHONDONTWRITEBYTECODE="1", NO_COLOR="1", FORCE_COLOR="0", CI="1")
    for name in ("TMPDIR", "XDG_CACHE_HOME", "npm_config_cache"):
        path = directory / name.lower()
        path.mkdir()
        env[name] = str(path)
    executions, receipts, errors, effective_commands = [], [], [], []
    for index, setup in enumerate(policy.get("setup", [])):
        log = directory / f"setup-{index}.log"
        code, _, _ = execute(setup["argv"], worktree, log, setup["timeout_seconds"], env)
        capture.add(log, "log")
        if code != 0:
            errors.append(f"Setup {index} failed with exit {code}")
            break
    if not errors:
        for index, check in enumerate(worker["checks"]):
            argv = list(check["argv"])
            log = directory / f"check-{index}.log"
            browser_output = directory / f"browser-{index}"
            if check["kind"] == "browser":
                # Runtime-owned reporter/output flags override project defaults.
                argv.extend(["--reporter=json", f"--output={browser_output}", "--workers=1", "--retries=0"])
            effective_commands.append(argv)
            code, start, finish = execute(argv, worktree, log, check["timeout_seconds"], env)
            log_id = capture.add(log, "log")
            executions.append({"command": shlex.join(check["argv"]), "cwd": str(worktree),
                               "started_at": start, "finished_at": finish, "exit_code": code, "log_artifact_id": log_id})
            tests, scenarios = None, []
            try:
                if check["kind"] == "browser":
                    # Playwright's JSON reporter writes the complete report to stdout.
                    tests, scenarios = browser_evidence(log, browser_output, check, capture)
                    capture.add(log, "test_report")
                elif check["kind"] in {"unit", "contract", "integration"}:
                    tests = text_test_counts(log.read_text(errors="replace"))
                if code != 0:
                    errors.append(f"{check['id']}: exit {code}")
            except (ValueError, OSError, KeyError, TypeError) as error:
                errors.append(f"{check['id']}: {error}")
            receipts.append({"id": check["id"], "worker_check_index": index, "tests": tests, "scenarios": scenarios})
    # Source edits by checks invalidate the evidence. Ignored caches are allowed.
    if git(worktree, "rev-parse", "HEAD") != commit or git(worktree, "status", "--porcelain"):
        errors.append("Verification modified the tested source revision")
    expected = {"run_id": plan["run_id"], "node_id": node, "attempt": attempt, "base_commit": plan["base_commit"],
                "output_commit": commit, "verification_cwd": str(worktree)}
    result = {"contract_version": "1.0.0", **{key: value for key, value in expected.items() if key != "verification_cwd"},
              "session_id": session_id, "status": "succeeded", "changed_files": changed,
              "checks": executions, "open_assumptions": [], "artifacts": capture.artifacts,
              "summary": f"Trusted {phase} check capture; not integration approval", "error": None}
    evidence = {"version": "1.0.0", "policy_sha256": policy_digest(policy),
                **{key: expected[key] for key in ("run_id", "node_id", "attempt", "output_commit")}, "checks": receipts}
    packet = {"phase": phase, "expected": expected, "result": result, "evidence": evidence,
              "artifact_root": str(artifacts_dir), "artifact_paths": {key: str(path) for key, path in capture.paths.items()},
              "capture_errors": errors, "effective_commands": effective_commands}
    packet = recheck_packet(packet, policy, run)
    save_json(packet_path, packet)
    return packet


def recheck_packet(packet: dict, policy: dict, run: Path) -> dict:
    root = Path(packet["artifact_root"]).resolve()
    if not root.is_relative_to(run.resolve()):
        raise ValueError("Artifact root outside run")
    gate = evaluate_worker(policy, packet["result"], packet["evidence"], expected=packet["expected"],
                           artifact_root=root, artifact_paths={key: Path(value) for key, value in packet["artifact_paths"].items()},
                           enforce_ownership=packet["phase"] == "worker")
    gate["reasons"].extend(packet["capture_errors"])
    if gate["reasons"]:
        gate["status"] = "blocked"
    packet["gate"] = gate
    return packet

"""Reusable policy/evidence gates. No agents, browsers, shells or graph launches.

Inputs must come from a trusted verifier plus backend-owned artifact registry, not
unchecked agent prose. Passing this evidence gate never authorizes integration.
"""
from __future__ import annotations

import hashlib
import json
import shlex
from datetime import datetime
from pathlib import Path

from jsonschema import Draft202012Validator, FormatChecker
from jsonschema.exceptions import ValidationError

CONTRACTS = Path(__file__).resolve().parents[1] / "contracts" / "workflow"


def validate_schema(name: str, value: dict) -> None:
    schema = json.loads((CONTRACTS / f"{name}.schema.json").read_text())
    Draft202012Validator(schema, format_checker=FormatChecker()).validate(value)


def policy_digest(policy: dict) -> str:
    """Canonical UTF-8 JSON: sorted keys, no whitespace, literal Unicode."""
    return hashlib.sha256(json.dumps(policy, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()).hexdigest()


def safe_path(value: str) -> str:
    normalized = value.rstrip("/")
    if not normalized or normalized.startswith("/") or any(char in normalized for char in "\\:*?[]") or any(part in {"", ".", ".."} for part in normalized.split("/")):
        raise ValueError(f"Not an exact repository-relative path/prefix: {value}")
    return normalized


def owns(path: str, prefix: str) -> bool:
    return path == prefix or path.startswith(prefix + "/")


def unique(items: list[dict], key: str) -> dict:
    result = {item[key]: item for item in items}
    if len(result) != len(items):
        raise ValueError(f"Duplicate {key}")
    return result


def validate_policy(policy: dict) -> dict:
    validate_schema("verification", policy)
    workers = unique(policy["workers"], "node_id")
    claimed = []
    for worker in workers.values():
        paths = [safe_path(path) for path in worker["owned_paths"]]
        for other_node, other_path in claimed:
            if any(owns(path, other_path) or owns(other_path, path) for path in paths):
                raise ValueError(f"Overlapping ownership: {worker['node_id']} and {other_node}")
        claimed.extend((worker["node_id"], path) for path in paths)
        checks = unique(worker["checks"], "id")
        if len({tuple(check["argv"]) for check in checks.values()}) != len(checks):
            raise ValueError("Each check needs a distinct command")
        kinds = {check["kind"] for check in checks.values()}
        required = {"build", "browser"} if worker["role"] == "frontend" else {"unit"}
        if not required <= kinds:
            raise ValueError(f"{worker['role']} requires {sorted(required)} checks")
        for check in checks.values():
            unique(check["scenarios"], "id")
            if (check["kind"] == "browser") != bool(check["scenarios"]):
                raise ValueError("Browser checks require named scenarios; other checks must not have scenarios")
    return policy


def evaluate_worker(policy: dict, result: dict, evidence: dict, *, expected: dict,
                    artifact_root: Path, artifact_paths: dict[str, Path], enforce_ownership: bool = True) -> dict:
    """Fail closed on absent, stale or inconsistent evidence.

    `expected` is backend-owned: run_id, node_id, attempt, base_commit,
    output_commit and verification_cwd. Caller must freeze edits and independently
    derive the full Git diff/commit before invoking; this function cannot prove
    that an agent has reported all changed files.
    """
    reasons = []
    try:
        validate_policy(policy)
        validate_schema("workerResult", result)
        validate_schema("verificationEvidence", evidence)
        workers = {worker["node_id"]: worker for worker in policy["workers"]}
        worker = workers[expected["node_id"]]
        for field in ("run_id", "node_id", "attempt", "base_commit", "output_commit"):
            if result[field] != expected[field]:
                raise ValueError(f"Worker result has stale/mismatched {field}")
        for field in ("run_id", "node_id", "attempt", "output_commit"):
            if evidence[field] != expected[field]:
                raise ValueError(f"Verification evidence has stale/mismatched {field}")
        if evidence["policy_sha256"] != policy_digest(policy):
            raise ValueError("Verification policy changed after evidence capture")
        if result["status"] != "succeeded" or result["output_commit"] is None or result["error"] is not None:
            raise ValueError("Worker did not produce a successful durable result")
        prefixes = [safe_path(path) for path in worker["owned_paths"]]
        for changed in result["changed_files"]:
            if enforce_ownership and not any(owns(safe_path(changed), prefix) for prefix in prefixes):
                reasons.append(f"Changed file outside ownership: {changed}")
        artifacts = unique(result["artifacts"], "artifact_id")
        root = artifact_root.resolve(strict=True)
        resolved = {}
        for artifact_id, artifact in artifacts.items():
            path = artifact_paths[artifact_id].resolve(strict=True)
            if not path.is_relative_to(root) or not path.is_file():
                raise ValueError(f"Artifact escapes registry root: {artifact_id}")
            with path.open("rb") as handle:
                digest = hashlib.file_digest(handle, "sha256").hexdigest()
            if digest != artifact["sha256"]:
                raise ValueError(f"Artifact hash mismatch: {artifact_id}")
            resolved[artifact_id] = path
        for check in result["checks"]:
            if artifacts.get(check["log_artifact_id"], {}).get("kind") != "log":
                reasons.append("Executed check is missing a log artifact")
            if datetime.fromisoformat(check["finished_at"]) < datetime.fromisoformat(check["started_at"]):
                reasons.append("Check finish precedes start")
            if check["exit_code"] != 0:
                reasons.append(f"Executed check failed: {check['command']}")
        supplied = unique(evidence["checks"], "id")
        required = {check["id"]: check for check in worker["checks"]}
        if set(supplied) != set(required):
            raise ValueError("Required check evidence missing or contains unknown check IDs")
        indexes = [check["worker_check_index"] for check in supplied.values()]
        if len(set(indexes)) != len(indexes):
            raise ValueError("A command execution cannot satisfy multiple check IDs")
        for check_id, requirement in required.items():
            receipt = supplied[check_id]
            execution = result["checks"][receipt["worker_check_index"]]
            if execution["command"] != shlex.join(requirement["argv"]):
                reasons.append(f"{check_id}: executed command differs from approved argv")
            if Path(execution["cwd"]).resolve() != Path(expected["verification_cwd"]).resolve():
                reasons.append(f"{check_id}: wrong verification worktree")
            duration = (datetime.fromisoformat(execution["finished_at"]) - datetime.fromisoformat(execution["started_at"])).total_seconds()
            if duration > requirement["timeout_seconds"]:
                reasons.append(f"{check_id}: execution exceeded approved timeout")
            if requirement["kind"] in {"unit", "browser", "integration", "contract"}:
                tests = receipt["tests"]
                if tests is None or tests["passed"] < 1 or tests["failed"] > 0:
                    reasons.append(f"{check_id}: no passing test evidence or failed tests")
            scenarios = unique(receipt["scenarios"], "id")
            if requirement["kind"] == "browser" and receipt["tests"] is not None and receipt["tests"]["passed"] < len(requirement["scenarios"]):
                reasons.append(f"{check_id}: fewer passing tests than required browser scenarios")
            if set(scenarios) != {scenario["id"] for scenario in requirement["scenarios"]}:
                reasons.append(f"{check_id}: missing/unknown browser scenarios")
            screenshot_ids = []
            for scenario in scenarios.values():
                artifact_id = scenario["screenshot_artifact_id"]
                if scenario["status"] != "passed":
                    reasons.append(f"{check_id}/{scenario['id']}: browser scenario did not pass")
                if artifact_id is None or artifacts.get(artifact_id, {}).get("kind") != "screenshot":
                    reasons.append(f"{check_id}/{scenario['id']}: screenshot required")
                    continue
                screenshot_ids.append(artifact_id)
                # Format sanity only, not proof of visual correctness/authenticity.
                with resolved[artifact_id].open("rb") as image:
                    header = image.read(24)
                if len(header) < 24 or header[:8] != b"\x89PNG\r\n\x1a\n" or header[12:16] != b"IHDR" or int.from_bytes(header[16:20], "big") == 0 or int.from_bytes(header[20:24], "big") == 0:
                    reasons.append(f"{check_id}/{scenario['id']}: expected a PNG screenshot")
            if len(set(screenshot_ids)) != len(screenshot_ids):
                reasons.append(f"{check_id}: each scenario needs a distinct screenshot artifact")
    except (ValueError, KeyError, IndexError, TypeError, OSError) as error:
        reasons.append(str(error))
    except ValidationError as error:
        reasons.append(error.message)
    return {"status": "blocked" if reasons else "passed", "reasons": reasons,
            "pending_gates": ["independent_review", "integration_approval"],
            "integration_allowed": False}

"""Read-only observer. Closing this process/pane cannot signal a Claude worker."""
from __future__ import annotations

import argparse
import json
import os
import re
import shlex
import subprocess
import sys
import time
from pathlib import Path

from .sessions import NODES, TERMINAL, read_json, save_json


def safe_text(value: str) -> str:
    # Strip terminal escape/control bytes before displaying model-controlled output.
    value = re.sub(r"\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)", "", value)
    value = re.sub(r"\x1b\[[0-?]*[ -/]*[@-~]", "", value)
    return "".join(char for char in value if char in "\n\t" or (char.isprintable() and char != "\x1b"))


def render(line: str) -> str:
    try:
        event = json.loads(line)
    except ValueError:
        return safe_text(line.rstrip())
    if not isinstance(event, dict):
        return ""
    if event.get("type") == "assistant":
        blocks = event.get("message", {}).get("content", [])
        return "\n".join(safe_text(block.get("text", "")) if block.get("type") == "text"
                         else f"[tool: {safe_text(str(block.get('name', 'unknown')))}]"
                         for block in blocks if isinstance(block, dict))
    if event.get("type") == "result":
        return safe_text(f"[{event.get('subtype', 'result')}] {event.get('result', '')}")
    if event.get("type") == "system":
        return safe_text(f"[system: {event.get('subtype', '')}]")
    return ""


def herdr(*args: str) -> dict:
    if os.environ.get("HERDR_ENV") != "1":
        raise RuntimeError("Herdr controls require a Herdr-managed caller pane (HERDR_ENV=1)")
    result = subprocess.run(["herdr", *args], capture_output=True, text=True, check=True, timeout=15)
    # Inspection/creation commands return JSON; rename/run may succeed silently.
    return json.loads(result.stdout) if result.stdout.strip() else {}


def open_panels(directory: Path) -> dict:
    """Only run the observer command in newly created panes; never Claude itself."""
    directory = directory.resolve()
    read_json(directory / "plan.json")
    mapping_path = directory / "observers.json"
    if mapping_path.exists():
        raise RuntimeError("Observer mapping already exists; inspect it before opening duplicate panes")
    current = herdr("pane", "current", "--current")["result"]["pane"]
    source = Path(__file__).resolve().parents[1]
    created = herdr("tab", "create", "--workspace", current["workspace_id"],
                    "--cwd", str(source), "--label", f"Workflow: {directory.name}", "--no-focus")["result"]
    tab_id = created["tab"]["tab_id"]
    pane = created["root_pane"]["pane_id"]
    mapping = {}
    for index, node in enumerate(NODES):
        if index == 0:
            new_pane = pane
        else:
            split = herdr("pane", "split", "--pane", pane, "--direction", "right",
                          "--cwd", str(source), "--no-focus")
            new_pane = split["result"]["pane"]["pane_id"]
        mapping[node] = {"pane_id": new_pane, "tab_id": tab_id, "mode": "read-only-observer"}
        save_json(mapping_path, mapping)  # Retain ownership even if the next command fails.
        herdr("pane", "rename", new_pane, f"Workflow {directory.name}: {node}")
        command = shlex.join([sys.executable, "-m", "workflow.observer", str(directory), node])
        herdr("pane", "run", new_pane, command)
        pane = new_pane
    return mapping


def watch(directory: Path, node: str, once: bool = False) -> None:
    print(f"READ-ONLY OBSERVER | {directory.name} / {node}\nClosing this pane does not stop Claude.", flush=True)
    offset = 0
    last_status = None
    while True:
        log = directory / f"{node}.stream.jsonl"
        if log.exists():
            with log.open("rb") as handle:
                handle.seek(offset)
                while True:
                    line = handle.readline()
                    if not line or not line.endswith(b"\n"):
                        break
                    offset = handle.tell()
                    text = render(line.decode(errors="replace"))
                    if text:
                        print(text, flush=True)
        state_path = directory / f"{node}.json"
        state = read_json(state_path) if state_path.exists() else {"status": "pending"}
        if state["status"] != last_status:
            last_status = state["status"]
            print(safe_text(f"[{last_status}] session={state.get('session_id', 'not launched')}"), flush=True)
            if state.get("error"):
                print(safe_text(state["error"]), flush=True)
        if once or last_status in TERMINAL:
            # Drain bytes written between the first read and the terminal receipt.
            if last_status in TERMINAL and log.exists():
                with log.open("rb") as handle:
                    handle.seek(offset)
                    for line in handle:
                        text = render(line.decode(errors="replace"))
                        if text:
                            print(text, flush=True)
            if not once and last_status in TERMINAL and os.environ.get("HERDR_ENV") == "1":
                try:
                    herdr("notification", "show", f"Workflow {node}: {last_status}",
                          "--body", f"Run {directory.name}; verification/review still required", "--sound", "none")
                except (OSError, ValueError, subprocess.SubprocessError):
                    pass  # Notification delivery never controls agent execution.
            print("Session receipt only — browser checks, review and integration are separate.", flush=True)
            return
        time.sleep(0.25)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("directory", type=Path)
    parser.add_argument("node", choices=NODES)
    parser.add_argument("--once", action="store_true")
    args = parser.parse_args()
    try:
        watch(args.directory.resolve(), args.node, args.once)
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main()

